#include <iostream>
#include <string>
#include <cctype>

std::string capitalizeWords(const std::string& input) {
    std::string result = input;
    bool newWord = true;
    for (size_t i = 0; i < result.size(); ++i) {
        if (std::isspace(result[i])) {
            newWord = true;
        } else if (newWord) {
            result[i] = std::toupper(result[i]);
            newWord = false;
        } else {
            result[i] = std::tolower(result[i]);
        }
    }
    return result;
}

